UPDATE recommend
SET country_id = #{countryId},
    city = #{city}
WHERE recommend_id = #{recommendId}

UPDATE recommend
SET recommend_rating = #{recommendRating},
    rating_content = #{ratingContent}
WHERE recommend_id = #{recommendId}

UPDATE recommend
SET deleted_at = SYSDATE
WHERE recommend_id = #{recommendId}
AND user_id = #{userId}
